//! Located edits and ownership checks for generated getter aliases.

use syn::spanned::Spanned;
use tracing::instrument;

use crate::loader::SharedParsedFile;

use super::super::inventory::call_site_attribute_is_stable;
use super::super::{Edit, is_static_str, span_range};
use super::derives::known_derive;
use super::names::Names;

#[instrument(level = "trace")]
pub(super) fn marker(owner: &str, field: &str) -> String {
    format!(
        "Generated by Cordial: error-field-storage v1; owner={owner}.{field}; getter-copy=inserted"
    )
}

#[instrument(level = "trace", skip(item))]
pub(super) fn marked(item: &syn::ItemType, owner: &str, field: &str) -> bool {
    item.attrs.iter().any(|attr| {
        matches!(&attr.meta, syn::Meta::NameValue(meta)
            if meta.path.is_ident("doc")
            && matches!(&meta.value, syn::Expr::Lit(lit)
                if matches!(&lit.lit, syn::Lit::Str(value) if value.value().trim() == marker(owner, field))))
    })
}

#[instrument(level = "debug", skip(file, item, field))]
pub(super) fn forward(
    file: &SharedParsedFile,
    item: &syn::ItemStruct,
    field: &syn::Field,
    name: &str,
) -> Option<Vec<Edit>> {
    if item.attrs.iter().any(|attr| {
        attr.path().is_ident("cfg")
            || (attr.path().is_ident("cfg_attr")
                && !call_site_attribute_is_stable(attr, &item.attrs, "file", file.syntax()))
    }) || !field_attrs_stable(file, item, field, false)
    {
        return None;
    }
    let owner = item.ident.to_string();
    let field_name = field.ident.as_ref()?.to_string();
    let (start, _) = span_range(file.source(), item.span())?;
    let (field_start, _) = span_range(file.source(), field.span())?;
    let cfg = cfg_attrs(file, &field.attrs)?.join("\n");
    let cfg = if cfg.is_empty() {
        cfg
    } else {
        format!("{cfg}\n")
    };
    Some(vec![
        Edit {
            start,
            end: start,
            replacement: format!(
                "\n/// {}\n{cfg}type {name} = &'static str;\n",
                marker(&owner, &field_name)
            ),
        },
        Edit {
            start: field_start,
            end: field_start,
            replacement: "#[getter(copy)] ".to_string(),
        },
    ])
}

#[instrument(level = "debug", skip(file, owner, item, field, names))]
pub(super) fn reverse(
    file: &SharedParsedFile,
    owner: &syn::ItemStruct,
    item: &syn::ItemType,
    field: &syn::Field,
    names: &Names,
) -> Option<Vec<Edit>> {
    if !field_attrs_stable(file, owner, field, true)
        || names.count(&item.ident.to_string()) != 2
        || !matches!(item.vis, syn::Visibility::Inherited)
        || !item.generics.params.is_empty()
        || item
            .attrs
            .iter()
            .filter(|attr| attr.path().is_ident("doc"))
            .count()
            != 1
        || item
            .attrs
            .iter()
            .any(|attr| !attr.path().is_ident("doc") && !attr.path().is_ident("cfg"))
        || !is_static_str(&item.ty)
    {
        return None;
    }
    let copies: Vec<_> = field
        .attrs
        .iter()
        .filter(|attr| {
            attr.path().is_ident("getter")
                && attr
                    .parse_args::<syn::Ident>()
                    .is_ok_and(|name| name == "copy")
        })
        .collect();
    let [copy] = copies.as_slice() else {
        return None;
    };
    if field
        .attrs
        .iter()
        .filter(|attr| attr.path().is_ident("getter"))
        .count()
        != 1
    {
        return None;
    }
    let alias_cfg = cfg_attrs(file, &item.attrs)?;
    let field_cfg = cfg_attrs(file, &field.attrs)?;
    if alias_cfg != field_cfg {
        return None;
    }
    let (start, end) = span_range(file.source(), item.span())?;
    let (copy_start, copy_end) = span_range(file.source(), copy.span())?;
    let end = end + usize::from(file.source().as_bytes().get(end) == Some(&b'\n'));
    let start = start
        .checked_sub(1)
        .filter(|start| file.source().as_bytes().get(*start) == Some(&b'\n'))
        .unwrap_or(start);
    let copy_end =
        copy_end + file.source()[copy_end..].len() - file.source()[copy_end..].trim_start().len();
    Some(vec![
        Edit {
            start,
            end,
            replacement: String::new(),
        },
        Edit {
            start: copy_start,
            end: copy_end,
            replacement: String::new(),
        },
    ])
}

/// derive_more's ignored fields do not participate in its Error implementation.
/// Preserve that annotation; other field macros still need an explicit contract.
#[instrument(level = "debug", skip(file, owner, field))]
fn field_attrs_stable(
    file: &SharedParsedFile,
    owner: &syn::ItemStruct,
    field: &syn::Field,
    generated: bool,
) -> bool {
    field.attrs.iter().all(|attr| {
        if attr.path().is_ident("doc") || attr.path().is_ident("cfg") {
            return true;
        }
        if generated && attr.path().is_ident("getter") {
            return attr
                .parse_args::<syn::Ident>()
                .is_ok_and(|name| name == "copy");
        }
        attr.path().is_ident("error")
            && attr
                .parse_args::<syn::Ident>()
                .is_ok_and(|name| name == "ignore")
            && owner
                .attrs
                .iter()
                .filter(|attr| attr.path().is_ident("derive"))
                .any(|attr| {
                    let mut found = false;
                    attr.parse_nested_meta(|meta| {
                        found |= known_derive(file.syntax(), &meta.path, "derive_more", "Error");
                        Ok(())
                    })
                    .is_ok()
                        && found
                })
    })
}

/// Copy only conditional compilation attributes that were present on the field.
#[instrument(level = "debug", skip(file, attrs))]
fn cfg_attrs(file: &SharedParsedFile, attrs: &[syn::Attribute]) -> Option<Vec<String>> {
    attrs
        .iter()
        .filter(|attr| attr.path().is_ident("cfg"))
        .map(|attr| {
            let (start, end) = span_range(file.source(), attr.span())?;
            Some(file.source().get(start..end)?.to_string())
        })
        .collect()
}
